const zone=(g:number)=>`Zona ${String.fromCharCode(65+g)}`;
const date=(s:string,short=false)=>s?new Intl.DateTimeFormat('es-AR',{timeZone:'America/Argentina/Cordoba',...(short?{day:'numeric',month:'short'}:{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}).format(new Date(s)):'Sin programar';
const statusLabel:Record<string,string>={draft:'Borrador',published:'Publicado',active:'En juego',finished:'Finalizado',archived:'Histórico',scheduled:'Programado',postponed:'Postergado',suspended:'Suspendido',cancelled:'Cancelado'};
function Crest({name,small=false}:{name:string;small?:boolean}){const hue=[...name].reduce((a,c)=>a+c.charCodeAt(0),0)%5;return <span className={`crest c${hue} ${small?'small':''}`}><Shield size={small?18:25} strokeWidth={1.5}/><b>{name.split(' ').map(w=>w[0]).slice(0,2).join('')}</b></span>}
function Badge({children,light=false}:{children:React.ReactNode;light?:boolean}){return <span className={`badge ${light?'light':''}`}><i/>{children}</span>}
export default function App({path}:{path:string[]}){
 const [tournaments,setTournaments]=useState<Tournament[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),[notice,setNotice]=useState(''),[token,setToken]=useState(''),[admin,setAdmin]=useState(false),[menu,setMenu]=useState(false);
 const isAdmin=path[0]==='admin';const isLogin=isAdmin&&path[1]==='login';
 async function load(access?:string){if(!access){setTournaments([]);setError('');setLoading(false);return;}setLoading(true);try{const res=await fetch('/api/tournaments',{headers:access?{Authorization:`Bearer ${access}`}:{},cache:'no-store'});const data=await res.json();if(!res.ok)throw Error(data.error);setTournaments(data);setError('');}catch(e){setError(e instanceof Error?e.message:'Error de conexión');}finally{setLoading(false);}}
 useEffect(()=>{let alive=true;const db=browserDb();const init=async(access:string)=>{if(!alive)return;setToken(access);if(access){const {data}=await db.from('profiles').select('enabled').single();if(alive)setAdmin(!!data?.enabled);}else setAdmin(false);await load(access);};db.auth.getSession().then(({data})=>init(data.session?.access_token||''));const {data:{subscription}}=db.auth.onAuthStateChange((_e,session)=>{setTimeout(()=>init(session?.access_token||''),0);});return()=>{alive=false;subscription.unsubscribe();};},[]);
 async function save(t:Tournament){const r=await fetch('/api/tournaments',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify(t)});const data=await r.json();if(!r.ok)throw Error(data.error);setTournaments(ts=>[data,...ts.filter(x=>x.id!==t.id)]);setNotice('Cambios guardados correctamente.');setTimeout(()=>setNotice(''),4000);return data as Tournament;}
 const selected=path[0]==='torneos'?tournaments.find(t=>t.slug===path[1]):isAdmin?tournaments.find(t=>t.id===path[2]):undefined;
 const publicTournaments=tournaments.filter(t=>t.status!=='draft');const managedTournaments=tournaments.filter(t=>t.access==='owner'||t.access==='editor');
 const matchT=path[0]==='partidos'?publicTournaments.find(t=>t.matches.some(m=>m.id===path[1]&&m.published)):undefined;
 return <><header className="header"><div className="header-inner"><Link href="/" className="brand"><span className="brand-icon"><Trophy size={23}/></span><span>gestor<span className="brand-secondary"> de torneos</span><small>EL JUEGO, ORGANIZADO.</small></span></Link><nav className={menu?'open':''}><Link className={!path.length?'active':''} href="/">Inicio</Link><Link className={path[0]==='torneos'?'active':''} href="/torneos">Torneos</Link><Link href="/torneos?historial=1">Historial</Link></nav><Link href="/admin" className={`admin-link ${isAdmin?'selected':''}`}><LayoutDashboard size={16}/><span>{token?'Mis torneos':'Ingresar'}</span><ArrowUpRight size={15}/></Link><button className="menu-button icon-button" aria-label="Abrir menú" onClick={()=>setMenu(!menu)}>{menu?<X/>:<Menu/>}</button></div></header>
 {notice&&<div role="status" className="toast"><CheckCircle2 size={18}/>{notice}</div>}
 <main>{error&&token?<div className="container empty"><AlertTriangle/><h2>No pudimos conectar</h2><p>{error}</p><button className="button" onClick={()=>load(token)}>Reintentar</button></div>:loading?<div className="loading"><Loader2 className="spin"/><p>Cargando la cancha…</p></div>:!token||!admin?<Login signedIn={!!token} onLogout={()=>browserDb().auth.signOut()}/>:isAdmin?<Admin tournaments={managedTournaments} selected={selected} path={path} save={save} onLogout={()=>browserDb().auth.signOut()}/>:matchT?<MatchDetail t={matchT} match={matchT.matches.find(m=>m.id===path[1])!}/>:path[0]==='partidos'?<NotFound/>:selected?<TournamentView t={selected} tab={path[2]||'resumen'}/>:path[0]==='torneos'&&path[1]?<NotFound/>:path[0]==='torneos'?<TournamentList tournaments={publicTournaments}/>:<Home tournaments={publicTournaments}/>}</main>
 <footer><div className="container footer-inner"><Link href="/" className="footer-brand"><Trophy size={18}/> gestor de torneos</Link><span>La pasión se juega. La organización se resuelve.</span><small>Hecho para el fútbol de acá.</small></div></footer></>;
}
function NotFound(){return <div className="container empty"><Trophy/><h1>No encontramos esta página</h1><Link className="button" href="/torneos">Ver torneos</Link></div>}
function Home({tournaments}:{tournaments:Tournament[]}){
 const [query,setQuery]=useState('');const active=tournaments.filter(t=>['active','published'].includes(t.status));const featured=active[0]||tournaments[0];const next=tournaments.flatMap(t=>t.matches.filter(m=>m.published&&m.status==='scheduled').map(m=>({t,m}))).sort((a,b)=>a.m.startsAt.localeCompare(b.m.startsAt)).slice(0,3);const last=tournaments.flatMap(t=>t.matches.filter(m=>m.published&&m.status==='finished').map(m=>({t,m}))).sort((a,b)=>b.m.startsAt.localeCompare(a.m.startsAt)).slice(0,4);
 return <><section className="hero"><div className="container hero-content"><div className="hero-copy"><span className="eyebrow"><span className="live-dot"/> TODO TU TORNEO. EN UN SOLO LUGAR.</span><h1>La pasión en la cancha.<br/><span>El torneo, acá.</span></h1><p>Seguí cada fecha, viví cada resultado y encontrá<br className="desktop"/> todo lo que pasa en tu torneo.</p><Link className="button lime" href="/torneos">Explorar torneos <ArrowUpRight size={18}/></Link><div className="hero-bottom"><span><Shield size={16}/> Fútbol local, bien organizado</span><span className="hero-line"/><span>Siempre a mano.</span></div></div><div className="pitch-art" aria-hidden="true"><div className="pitch-frame"><div className="pitch-mid"/><div className="pitch-circle"/><div className="goal-area left"/><div className="goal-area right"/></div><div className="pitch-coord">34° 36′ S &nbsp; 58° 22′ O</div><div className="ball">✦</div></div><div className="hero-chip"><span className="live-dot"/> EL PRÓXIMO PARTIDO EMPIEZA ACÁ <ArrowUpRight size={15}/></div></div></section>
 <div className="container home-main"><div className="stats-strip"><div><strong>{active.length.toString().padStart(2,'0')}</strong><span>Torneos en juego</span></div><div><strong>{tournaments.reduce((n,t)=>n+t.entrants.length,0)}</strong><span>Equipos participantes</span></div><div><strong>{tournaments.reduce((n,t)=>n+t.matches.filter(m=>m.published&&m.status==='finished').length,0)}</strong><span>Partidos disputados</span></div><span className="strip-note"><span className="live-dot"/> Actualizado en cada fecha</span></div>
 <div className="section-heading"><div><span className="overline">LA COMPETENCIA SIGUE</span><h2>Torneos en juego<span className="count">{active.length}</span></h2></div><Link href="/torneos" className="text-link">Ver todos los torneos <ArrowRight size={16}/></Link></div><div className="tournament-grid">{active.slice(0,3).map((t,i)=><TournamentCard key={t.id} t={t} index={i}/>)}{!active.length&&<p className="empty-inline">Todavía no hay torneos publicados.</p>}</div>
 <div className="two-cols"><section><div className="section-heading compact"><div><span className="overline">AGENDÁ LA PRÓXIMA</span><h2>Se viene la fecha</h2></div><CalendarDays size={21}/></div><div className="panel">{next.map(({t,m})=><MatchRow key={m.id} t={t} m={m}/>)}{!next.length&&<p className="empty-inline">No hay partidos programados.</p>}<Link className="panel-bottom" href={featured?`/torneos/${featured.slug}/fixture`:'/torneos'}>Ver fixture completo <ArrowRight size={16}/></Link></div></section><section><div className="section-heading compact"><div><span className="overline">ASÍ TERMINARON</span><h2>Últimos resultados</h2></div><Goal size={22}/></div><div className="panel">{last.map(({t,m})=><MatchRow key={m.id} t={t} m={m} compact/>)}{!last.length&&<p className="empty-inline">Los primeros resultados aparecerán acá.</p>}</div></section></div>
 <section className="organizer-callout"><span className="callout-icon"><ClipboardList size={32}/></span><div><h3>Que la organización también juegue en equipo.</h3><p>Torneos, fixtures y resultados. Todo bajo control, desde un solo panel.</p></div><Link className="button outline" href="/admin">Ir a administración <ArrowUpRight size={17}/></Link></section></div></>;
}
function TournamentCard({t,index=0}:{t:Tournament;index?:number}){return <Link className="tournament-card" href={`/torneos/${t.slug}`}><div className={`card-banner banner-${index%3}`}><div className="banner-lines"/><Badge light>{statusLabel[t.status]}</Badge><span className="tournament-emblem"><Trophy size={38} strokeWidth={1.3}/></span><span className="season-tag">TEMPORADA {t.season}</span></div><div className="card-body"><span className="overline">{t.category}</span><h3>{t.name}<ArrowUpRight size={20}/></h3><p>{t.visibility==='private'?'🔒 Privado · ':''}{t.demo?'Torneo ficticio de demostración':t.description||'Toda la información de la competencia'}</p><div className="card-meta"><span><Users size={14}/>{t.entrants.length} equipos</span><span><Shield size={14}/>{t.settings.groups} zonas</span><span className="card-arrow"><ArrowRight size={18}/></span></div></div></Link>}
function TournamentList({tournaments}:{tournaments:Tournament[]}){const[query,setQuery]=useState(''),[filter,setFilter]=useState('all');useEffect(()=>{if(new URLSearchParams(location.search).get('historial'))setFilter('history');},[]);const ts=tournaments.filter(t=>t.name.toLowerCase().includes(query.toLowerCase())&&(filter==='all'||filter==='active'&&['active','published'].includes(t.status)||filter==='history'&&['finished','archived'].includes(t.status)));return <div className="container page"><span className="overline">ENCONTRÁ TU COMPETENCIA</span><h1>Todos los torneos</h1><p className="muted">El presente y la historia de cada campeonato.</p><div className="toolbar"><div className="segmented">{[['all','Todos'],['active','En juego'],['history','Históricos']].map(([v,l])=><button className={filter===v?'active':''} onClick={()=>setFilter(v)} key={v}>{l}</button>)}</div><label className="search"><Search size={17}/><input aria-label="Buscar torneo" placeholder="Buscar un torneo…" value={query} onChange={e=>setQuery(e.target.value)}/></label></div><div className="tournament-grid">{ts.map((t,i)=><TournamentCard key={t.id} t={t} index={i}/>)}</div>{!ts.length&&<div className="empty"><Trophy/><h3>No hay torneos para mostrar</h3><p>Probá con otro filtro.</p></div>}</div>}
function MatchRow({t,m,compact=false}:{t:Tournament;m:Match;compact?:boolean}){const h=t.entrants.find(e=>e.id===m.home),a=t.entrants.find(e=>e.id===m.away);return <Link href={`/partidos/${m.id}`} className={`match-row ${compact?'compact-row':''}`}><div className="match-label"><span>{t.name} <b>·</b> Fecha {m.round}</span><span>{m.status==='finished'?'FINAL':date(m.startsAt,true)}</span></div><div className="versus"><span className="team home"><Crest name={h?.name||'?'} small/>{h?.name}</span><span className={`score ${m.status!=='finished'?'upcoming':''}`}>{m.status==='finished'?`${m.homeScore} – ${m.awayScore}`:m.startsAt?new Intl.DateTimeFormat('es-AR',{hour:'2-digit',minute:'2-digit',timeZone:t.settings.timezone}).format(new Date(m.startsAt)):'vs'}</span><span className="team away">{a?.name}<Crest name={a?.name||'?'} small/></span></div>{!compact&&<div className="match-foot"><span><MapPin size={12}/>{m.pitch}</span><span>{m.kind==='interzonal'?'Interzonal':m.group!==null?zone(m.group):'Playoff'}<ChevronRight size={13}/></span></div>}</Link>}
function TournamentView({t,tab}:{t:Tournament;tab:string}){const [round,setRound]=useState('all'),[group,setGroup]=useState('all'),[team,setTeam]=useState('all'),[pitch,setPitch]=useState('all');const matches=t.matches.filter(m=>m.published);const rows=standings(t);const ranking=rankings(t);const tabs=[['resumen','Resumen'],['fixture','Fixture y resultados'],['posiciones','Posiciones'],['goleadores','Goleadores'],['disciplina','Disciplina'],['equipos','Equipos'],['reglamento','Reglamento']];return <><section className="tournament-hero"><div className="container"><Link href="/torneos" className="breadcrumb"><ChevronLeft size={14}/> Todos los torneos</Link><div className="tournament-title"><span className="big-emblem"><Trophy size={43}/></span><div><div className="inline"><span className="overline">{t.visibility==='private'?'PRIVADO · ':''}TEMPORADA {t.season} · {t.category}</span><Badge light>{statusLabel[t.status]}</Badge></div><h1>{t.name}</h1><p>{t.description}</p></div><button className="button outline-light" onClick={()=>window.open(`https://wa.me/?text=${encodeURIComponent(t.name+' '+location.href)}`,'_blank','noopener,noreferrer')}><Share2 size={16}/> Compartir</button></div>{t.demo&&<span className="demo-note">DEMOSTRACIÓN · Equipos, jugadores y resultados ficticios.</span>}</div></section><div className="tab-bar"><div className="container tabs">{tabs.map(([v,l])=><Link key={v} className={tab===v?'active':''} href={`/torneos/${t.slug}${v==='resumen'?'':'/'+v}`}>{l}</Link>)}</div></div><div className="container page tournament-content">
 {tab==='resumen'&&<><div className="detail-stats">{[[t.entrants.length,'Equipos'],[matches.length,'Partidos'],[matches.filter(m=>m.status==='finished').length,'Finalizados'],[matches.reduce((n,m)=>n+(m.status==='finished'?(m.homeScore||0)+(m.awayScore||0):0),0),'Goles']].map(([v,l])=><div key={l}><strong>{v}</strong><span>{l}</span></div>)}</div><div className="two-cols"><section><div className="section-heading compact"><h2>Próximos partidos</h2><Link className="text-link" href={`/torneos/${t.slug}/fixture`}>Ver fixture <ArrowRight size={15}/></Link></div><div className="panel">{matches.filter(m=>m.status==='scheduled').slice(0,4).map(m=><MatchRow key={m.id} t={t} m={m}/>)}</div></section><section><div className="section-heading compact"><h2>Últimos resultados</h2></div><div className="panel">{matches.filter(m=>m.status==='finished').slice(-4).map(m=><MatchRow key={m.id} t={t} m={m}/>)}</div></section></div></>}
 {tab==='fixture'&&<><div className="section-heading"><div><span className="overline">CADA CRUCE, CADA FECHA</span><h2>Fixture y resultados</h2></div><button className="button secondary print-button" onClick={()=>window.print()}>Imprimir</button></div><div className="filters"><label>Fecha<select value={round} onChange={e=>setRound(e.target.value)}><option value="all">Todas las fechas</option>{[...new Set(matches.map(m=>m.round))].map(r=><option value={r} key={r}>Fecha {r}</option>)}</select></label><label>Zona<select value={group} onChange={e=>setGroup(e.target.value)}><option value="all">Todas las zonas</option>{Array.from({length:t.settings.groups},(_,g)=><option value={g} key={g}>{zone(g)}</option>)}<option value="interzonal">Interzonales</option></select></label><label>Equipo<select value={team} onChange={e=>setTeam(e.target.value)}><option value="all">Todos los equipos</option>{t.entrants.map(e=><option value={e.id} key={e.id}>{e.name}</option>)}</select></label><label>Cancha<select value={pitch} onChange={e=>setPitch(e.target.value)}><option value="all">Todas las canchas</option>{t.settings.pitches.map(p=><option key={p}>{p}</option>)}</select></label></div>{[...new Set(matches.map(m=>m.round))].sort((a,b)=>a-b).filter(r=>round==='all'||r===+round).map(r=>{const ms=matches.filter(m=>m.round===r&&(group==='all'||group==='interzonal'&&m.kind==='interzonal'||m.group===+group)&&(team==='all'||m.home===team||m.away===team)&&(pitch==='all'||m.pitch===pitch)).sort((a,b)=>a.slot-b.slot||a.pitch.localeCompare(b.pitch));const byes=t.entrants.filter(e=>!matches.some(m=>m.round===r&&(m.home===e.id||m.away===e.id)));return <section className="round-section" key={r}><div className="round-heading"><h3>Fecha {r.toString().padStart(2,'0')}</h3><span>{date(matches.find(m=>m.round===r)?.startsAt||'',true)}</span></div><div className="fixtures-grid">{ms.map(m=><div className="panel" key={m.id}><MatchRow t={t} m={m}/></div>)}</div>{!ms.length&&<p className="muted">No hay partidos para estos filtros.</p>}{byes.length>0&&<p className="bye">Libres: {byes.map(e=>e.name).join(', ')}</p>}</section>})}</>}
 {tab==='posiciones'&&<><h2>Tabla de posiciones</h2><p className="muted">Victoria {t.settings.win} pts · Empate {t.settings.draw} pts · Derrota {t.settings.loss} pts</p><p className="info-line">Interzonales: {t.settings.interzonalPoints?'suman puntos en la zona de cada equipo':'exhibición, no suman puntos'}. Desempates: {t.settings.tieBreakers.map(k=>({points:'puntos',difference:'DG',goals:'GF',headToHead:'enfrentamiento directo',ppg:'puntos por partido'}[k])).join(' → ')}.</p>{Array.from({length:t.settings.groups},(_,g)=><section className="table-section" key={g}><h3>{zone(g)}</h3><div className="table-scroll panel"><table><thead><tr><th>#</th><th>Equipo</th>{['PJ','PG','PE','PP','GF','GC','DG','PTS'].map(l=><th key={l}>{l}</th>)}{t.settings.tieBreakers.includes('ppg')&&<th>PPP</th>}</tr></thead><tbody>{rows.filter(r=>r.group===g).map((r,i)=><tr key={r.id}><td>{i+1}</td><td><span className="inline"><Crest name={r.name} small/>{r.name}</span></td>{[r.played,r.won,r.drawn,r.lost,r.gf,r.ga,r.difference].map((v,j)=><td key={j}>{v}</td>)}<td><b className="points">{r.points}</b></td>{t.settings.tieBreakers.includes('ppg')&&<td>{r.ppg.toFixed(2)}</td>}</tr>)}</tbody></table></div>{new Set(rows.filter(r=>r.group===g).map(r=>r.played)).size>1&&<p className="info-line">Los equipos tienen distinta cantidad de partidos jugados.</p>}</section>)}</>}
 {(tab==='goleadores'||tab==='disciplina')&&<><h2>{tab==='goleadores'?'Los goleadores':'Disciplina'}</h2><p className="muted">{t.settings.interzonalStats?'Incluye eventos de interzonales.':'No incluye eventos de interzonales.'} Los goles en contra no se atribuyen al ranking de goleadores.</p><div className="table-scroll panel"><table><thead><tr><th>#</th><th>Jugador</th><th>Equipo</th>{tab==='goleadores'?<th>Goles</th>:<><th>Amarillas</th><th>Rojas</th><th>Revisión</th></>}</tr></thead><tbody>{ranking.filter(r=>tab==='goleadores'?r.goals>0:r.yellow+r.red>0).sort((a,b)=>tab==='goleadores'?b.goals-a.goals:b.red-a.red||b.yellow-a.yellow).map((r,i)=><tr key={`${r.entrantId}-${r.id}`}><td>{i+1}</td><td><b>{r.name}</b></td><td>{r.team}</td>{tab==='goleadores'?<td><span className="points">{r.goals}</span></td>:<><td>{r.yellow}</td><td>{r.red}</td><td>{r.red||r.yellow>=t.settings.yellowLimit?'Requiere resolución':'—'}</td></>}</tr>)}</tbody></table>{!ranking.some(r=>tab==='goleadores'?r.goals:r.yellow+r.red)&&<p className="empty-inline">Todavía no hay eventos registrados.</p>}</div>{tab==='disciplina'&&<p className="info-line">Umbral de amarillas: {t.settings.yellowLimit}. Las sanciones requieren resolución del organizador; no se presume cumplimiento automático.</p>}</>}
 {tab==='equipos'&&<><h2>Los protagonistas</h2><div className="teams-grid">{t.entrants.map(e=><article className="panel team-card" key={e.id}><div className="inline"><Crest name={e.name}/><div><span className="overline">{zone(e.group)}</span><h3>{e.name}</h3></div></div><details><summary>Ver plantel · {e.players.length} jugadores</summary>{e.players.map(p=><div className="roster-row" key={p.id}><span className="number">{p.number}</span>{p.name}</div>)}</details></article>)}</div></>}
 {tab==='reglamento'&&<div className="panel prose"><h2>Reglamento</h2><p style={{whiteSpace:'pre-wrap'}}>{t.rules||'El organizador todavía no cargó el reglamento.'}</p></div>}
 </div></>}
function MatchDetail({t,match:m}:{t:Tournament;match:Match}){const h=t.entrants.find(e=>e.id===m.home)!,a=t.entrants.find(e=>e.id===m.away)!;return <div className="container page"><Link className="breadcrumb dark" href={`/torneos/${t.slug}/fixture`}><ChevronLeft size={14}/> {t.name} · Fixture</Link><div className="panel match-detail"><Badge>{statusLabel[m.status]}</Badge><p>Fecha {m.round} · {m.kind==='interzonal'?'Interzonal':m.group!==null?zone(m.group):'Playoff'}</p><div className="detail-score"><div><Crest name={h.name}/><h2>{h.name}</h2></div><strong>{m.status==='finished'?`${m.homeScore} – ${m.awayScore}`:'vs'}</strong><div><Crest name={a.name}/><h2>{a.name}</h2></div></div><p className="muted">{date(m.startsAt)} · {m.pitch}</p></div><div className="panel prose"><h3>Lo que pasó en el partido</h3>{m.events.filter(e=>!e.voided).sort((a,b)=>(a.minute||0)-(b.minute||0)).map(e=>{const team=t.entrants.find(t=>t.id===e.teamId);return <div className="event-line" key={e.id}><span>{e.minute??'—'}′</span><span className={`event-symbol ${e.type}`}>{e.type==='goal'||e.type==='own_goal'?<Goal size={18}/>:<span/>}</span><b>{team?.players.find(p=>p.id===e.playerId)?.name}</b><small>{({goal:'Gol',own_goal:'Gol en contra',yellow:'Amarilla',red:'Roja',second_yellow:'Doble amarilla'}[e.type])} · {team?.name}</small></div>})}{!m.events.some(e=>!e.voided)&&<p className="muted">Sin eventos individuales registrados.</p>}{m.note&&<p>{m.note}</p>}</div></div>}
function Login({signedIn,onLogout}:{signedIn:boolean;onLogout:()=>void}){
 const[email,setEmail]=useState(''),[password,setPassword]=useState(''),[mode,setMode]=useState<'password'|'link'|'register'>('link'),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);
 async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setMessage('');try{const db=browserDb();if(mode==='link'){const {error}=await db.auth.signInWithOtp({email,options:{shouldCreateUser:false,emailRedirectTo:location.origin+'/admin'}});if(error)throw error;setMessage('Si tu cuenta está registrada, recibirás un enlace de acceso. Revisá también Spam.');}else if(mode==='register'){const {data,error}=await db.auth.signUp({email,password,options:{emailRedirectTo:location.origin+'/admin'}});if(error)throw error;if(data.session){location.href='/';return;}setMessage('Revisá tu correo y confirmá tu cuenta. Después podés ver los torneos y crear los tuyos. Si ya tenés cuenta, usá Ingresar.');}else{const {error}=await db.auth.signInWithPassword({email,password});if(error)throw error;location.href='/';}}catch(e){const text=e instanceof Error?e.message:'No pudimos iniciar sesión.';setMessage(text.includes('Invalid login')?'Correo o contraseña incorrectos.':text.includes('Email not confirmed')?'Confirmá tu cuenta desde el correo antes de ingresar.':text.includes('rate limit')?'Se alcanzó el límite de correos. Esperá unos minutos antes de reintentar.':text.includes('Signups not allowed')?'Primero creá tu cuenta desde la pestaña Crear cuenta.':text);}finally{setBusy(false);}}
 return <div className="login-wrap"><div className="panel login-panel"><span className="brand-icon"><Trophy size={24}/></span><span className="overline">TU COMUNIDAD DE TORNEOS</span><h1>{mode==='register'?'Tu lugar en el juego.':'Volvé al juego.'}</h1><p className="muted">Registrate para seguir los torneos. Cuando creás uno, sos su administrador.</p>{signedIn?<><p>Tu cuenta no está habilitada o falta confirmar el correo. Volvé a ingresar después de confirmar tu cuenta.</p><button className="button" onClick={onLogout}>Cerrar sesión</button></>:<><div className="segmented auth-tabs"><button className={mode!=='register'?'active':''} onClick={()=>{setMode('link');setMessage('');}}>Ingresar</button><button className={mode==='register'?'active':''} onClick={()=>{setMode('register');setMessage('');}}>Crear cuenta</button></div><form onSubmit={submit}><label>Correo electrónico<input required type="email" autoComplete="email" placeholder="tu@correo.com" value={email} onChange={e=>setEmail(e.target.value)}/></label>{mode!=='link'&&<label>Contraseña<input required minLength={8} maxLength={128} type="password" autoComplete={mode==='register'?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)}/>{mode==='register'&&<small>Mínimo 8 caracteres.</small>}</label>}<button disabled={busy} className="button full">{busy?<Loader2 className="spin" size={18}/>:mode==='register'?'Crear mi cuenta':mode==='link'?'Recibir enlace de acceso':'Ingresar'}<ArrowRight size={17}/></button>{mode!=='register'&&<button type="button" className="text-link login-mode" onClick={()=>{setMode(mode==='link'?'password':'link');setMessage('');}}>{mode==='link'?'Ingresar con contraseña':'Recibir un enlace por correo'}</button>}</form></>}{message&&<p role="status" className="info-line">{message}</p>}<p className="login-help"><Shield size={13}/> Todos ingresan con una cuenta.<br/>Ver un torneo no permite editarlo.</p></div></div>;
}
function Admin({tournaments,selected,path,save,onLogout}:{tournaments:Tournament[];selected?:Tournament;path:string[];save:(t:Tournament)=>Promise<Tournament>;onLogout:()=>void}){const[tab,setTab]=useState('dashboard');useEffect(()=>{setTab(path[1]==='auditoria'?'audit':'dashboard');},[path]);return <div className="admin-shell"><aside className="admin-sidebar"><span className="overline">ÁREA PRIVADA</span><h3>Mis torneos</h3><Link className={tab==='dashboard'?'active':''} href="/admin"><LayoutDashboard size={18}/> Panel general</Link><Link href="/admin/torneos/nuevo"><Plus size={18}/> Crear torneo</Link><Link className={tab==='audit'?'active':''} href="/admin/auditoria"><ClipboardList size={18}/> Auditoría</Link><div className="sidebar-bottom"><span className="secure-note"><Lock size={15}/> Conexión protegida</span><button onClick={onLogout}><LogOut size={16}/> Cerrar sesión</button></div></aside><div className="admin-main">{path[1]==='torneos'&&path[2]==='nuevo'?<TournamentEditor key="new" save={save}/>:selected&&(selected.access==='owner'||selected.access==='editor')?<TournamentEditor key={selected.id} initial={selected} save={save}/>:tab==='audit'?<Audit/>:<><div className="section-heading"><div><span className="overline">TODO LISTO PARA LA PRÓXIMA FECHA</span><h1>Mis torneos</h1><p className="muted">Administrá los torneos que creaste o donde colaborás. El resto lo podés ver en Torneos.</p></div><Link className="button" href="/admin/torneos/nuevo"><Plus size={18}/> Crear torneo</Link></div><div className="admin-stats">{[[tournaments.length,'Torneos creados',Trophy],[tournaments.filter(t=>t.status==='active').length,'Torneos activos',Goal],[tournaments.reduce((n,t)=>n+t.matches.filter(m=>m.status==='scheduled').length,0),'Resultados pendientes',CalendarDays]].map(([n,l,Icon])=>{const I=Icon as typeof Trophy;return <div className="panel" key={l as string}><I size={22}/><strong>{n as number}</strong><span>{l as string}</span></div>})}</div><div className="section-heading"><h2>Mis torneos</h2><span className="muted">{tournaments.length} en total</span></div><div className="admin-tournaments">{tournaments.map(t=><Link href={`/admin/torneos/${t.id}`} className="panel admin-tournament" key={t.id}><span className="admin-trophy"><Trophy size={24}/></span><div><h3>{t.name}</h3><p>{t.access==='owner'?'Propietario':'Colaborador'} · {t.visibility==='private'?'Privado':'Público'} · {t.season} · {t.entrants.length} equipos {t.demo?'· DEMO':''}</p></div><Badge>{statusLabel[t.status]}</Badge><ChevronRight size={20}/></Link>)}{!tournaments.length&&<div className="empty panel"><Trophy/><h3>El próximo torneo empieza con vos.</h3><Link href="/admin/torneos/nuevo" className="button">Crear mi primer torneo</Link></div>}</div></>}</div></div>}
function Audit(){const[rows,setRows]=useState<{id:number;action:string;entity_id:string;created_at:string;actor_user_id:string}[]>([]),[error,setError]=useState('');useEffect(()=>{browserDb().from('audit_logs').select('id,action,entity_id,created_at,actor_user_id').order('created_at',{ascending:false}).limit(100).then(({data,error})=>{if(error)setError(error.message);else setRows(data||[]);});},[]);return <><span className="overline">TRAZABILIDAD</span><h1>Auditoría</h1><p className="muted">Últimas 100 operaciones de tus torneos. Los valores anteriores y posteriores se preservan en la base de datos.</p>{error&&<p role="alert">{error}</p>}<div className="panel table-scroll"><table><thead><tr><th>Fecha</th><th>Operación</th><th>Torneo</th><th>Administrador</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{date(r.created_at)}</td><td>{r.action}</td><td><Link href={`/admin/torneos/${r.entity_id}`}>{r.entity_id.slice(0,8)}</Link></td><td>{r.actor_user_id?.slice(0,8)||'Sistema / demo'}</td></tr>)}</tbody></table></div></>}
function blankTournament():Tournament{return{visibility:'public',access:'owner',id:uid(),slug:'',name:'',season:'2026',category:'Primera',description:'',rules:'',status:'draft',version:0,demo:false,settings:structuredClone(defaultSettings),entrants:[],matches:[]}}
function TournamentEditor({initial,save}:{initial?:Tournament;save:(t:Tournament)=>Promise<Tournament>}){
 const[t,setT]=useState<Tournament>(()=>initial?structuredClone(initial):blankTournament()),[step,setStep]=useState(initial?2:0),[busy,setBusy]=useState(false),[error,setError]=useState(''),[success,setSuccess]=useState(''),[names,setNames]=useState(''),[warnings,setWarnings]=useState<string[]>([]),[editing,setEditing]=useState<string|null>(null),[dirty,setDirty]=useState(false),[filterRound,setFilterRound]=useState('all');
 const update=(patch:Partial<Tournament>)=>{setT(v=>({...v,...patch}));setDirty(true);setSuccess('');};const settings=(patch:Partial<Tournament['settings']>)=>{if(t.matches.length){setError('Para cambiar reglas del formato, creá otro torneo o eliminá primero el fixture sin resultados.');return;}update({settings:{...t.settings,...patch}});};
 useEffect(()=>{const handler=(e:BeforeUnloadEvent)=>{if(dirty){e.preventDefault();}};window.addEventListener('beforeunload',handler);return()=>window.removeEventListener('beforeunload',handler);},[dirty]);
 async function persist(value=t){setError('');setBusy(true);try{const saved=await save(value);setT(saved);setDirty(false);setSuccess('Guardado.');if(!initial)history.replaceState(null,'',`/admin/torneos/${saved.id}`);return saved;}catch(e){setError(e instanceof Error?e.message:'No pudimos guardar.');}finally{setBusy(false);}}
 function addTeams(){if(t.matches.length)return;const list=names.split('\n').map(n=>n.trim()).filter(Boolean);if(!list.length)return;const existing=new Set(t.entrants.map(e=>e.name.toLowerCase()));if(list.some(n=>existing.has(n.toLowerCase()))||new Set(list.map(n=>n.toLowerCase())).size!==list.length){setError('Hay nombres de equipos repetidos.');return;}update({entrants:[...t.entrants,...list.map((name,i)=>({id:uid(),name,group:(t.entrants.length+i)%t.settings.groups,players:[]}))]});setNames('');}
 function generate(reschedule=false){setError('');try{if(t.settings.mode==='manual'&&!reschedule)throw Error('Para generar la primera programación usá rotación o distribución equilibrada. Después podés editarla manualmente.');if(!reschedule&&t.matches.length&&!confirm('Se reemplazará el fixture actual. Los resultados no pueden regenerarse. ¿Continuar?'))return;if(!reschedule&&t.matches.some(m=>m.status==='finished'))throw Error('No se puede reemplazar un fixture que tiene resultados.');const source=reschedule?t.matches:pairings(t.entrants,t.settings);const planned=schedule(source,t.settings);update({matches:planned.matches});setWarnings(planned.warnings);setSuccess(`Programación generada. Costo de equidad: ${planned.penalty}. Revisá el reporte antes de publicar.`);}catch(e){setError(e instanceof Error?e.message:'Error de generación.');}}
 async function publish(){if(!confirm('El torneo, su fixture y los resultados serán visibles según la privacidad elegida: público para usuarios registrados o privado para tus colaboradores. ¿Publicar?'))return;const issues=validateFixture(t.matches,t.settings);if(issues.length){setError(issues.join(' '));return;}await persist({...t,status:t.status==='draft'?'published':t.status,matches:t.matches.map(m=>({...m,published:true}))});}
 const stepNames=['Configuración','Equipos y planteles','Fixture y resultados','Equidad y publicación','Accesos'];
 return <><Link href="/admin" className="breadcrumb dark"><ChevronLeft size={15}/> Volver al panel</Link><div className="section-heading"><div><span className="overline">{t.version?'GESTIONAR TORNEO':'NUEVO TORNEO'}</span><h1>{t.name||'Prepará tu competencia'}</h1><p className="muted">{dirty?'Tenés cambios sin guardar.':`Versión ${t.version} · ${statusLabel[t.status]}`}</p></div><button className="button" disabled={busy} onClick={()=>persist()}>{busy?<Loader2 className="spin" size={16}/>:<Check size={17}/>} Guardar {t.status==='draft'?'borrador':'cambios'}</button></div>
 <div className="wizard-tabs">{stepNames.map((label,i)=><button key={i} className={step===i?'active':''} onClick={()=>setStep(i)}><span>{i+1}</span>{label}</button>)}</div>
 {error&&<div role="alert" className="alert error"><AlertTriangle size={18}/><span>{error}</span><button aria-label="Cerrar error" className="icon-button" onClick={()=>setError('')}><X size={16}/></button></div>}{success&&<div role="status" className="alert success"><CheckCircle2 size={17}/>{success}</div>}
 {step===0&&<><section className="panel form-panel"><h2>Visibilidad del torneo</h2><label>¿Quién puede verlo?<select value={t.visibility||'public'} disabled={t.access==='editor'} onChange={e=>{if(t.version&&t.visibility==='private'&&e.target.value==='public'&&!confirm('El torneo será visible para todos los usuarios registrados al guardar. ¿Continuar?'))return;update({visibility:e.target.value as 'public'|'private'});}}><option value="public">Público · Todos los usuarios registrados</option><option value="private">Privado · Propietario y colaboradores</option></select></label><p className="info-line">La visibilidad no da permiso de edición. Solo el propietario puede cambiarla o autorizar colaboradores. Los borradores siempre se mantienen privados.</p></section><section className="panel form-panel"><h2>La identidad del torneo</h2><p className="muted">Empecemos por lo que todos van a ver.</p><div className="form-grid"><label>Nombre del torneo<input value={t.name} maxLength={100} onChange={e=>update({name:e.target.value,...(!t.version?{slug:e.target.value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}: {})})} placeholder="Ej. Copa de Verano"/></label><label>Enlace público<input value={t.slug} onChange={e=>update({slug:e.target.value})}/></label><label>Temporada<input value={t.season} onChange={e=>update({season:e.target.value})}/></label><label>Categoría<input value={t.category} onChange={e=>update({category:e.target.value})}/></label><label className="span-2">Descripción<textarea value={t.description} onChange={e=>update({description:e.target.value})} rows={2}/></label><label className="span-2">Reglamento<textarea value={t.rules} onChange={e=>update({rules:e.target.value})} rows={4}/></label></div></section><section className="panel form-panel"><h2>Formato y reglas</h2><div className="form-grid"><label>Cantidad de zonas<input type="number" min={1} max={16} value={t.settings.groups} onChange={e=>settings({groups:+e.target.value})}/></label><label>Ruedas<select value={t.settings.legs} onChange={e=>settings({legs:+e.target.value})}><option value="1">Ida</option><option value="2">Ida y vuelta</option></select></label><div className="form-grid span-2 three"><label>Puntos por victoria<input type="number" min={0} value={t.settings.win} onChange={e=>settings({win:+e.target.value})}/></label><label>Puntos por empate<input type="number" min={0} value={t.settings.draw} onChange={e=>settings({draw:+e.target.value})}/></label><label>Puntos por derrota<input type="number" min={0} value={t.settings.loss} onChange={e=>settings({loss:+e.target.value})}/></label></div><label className="span-2">Desempates (orden de prioridad)<select value={t.settings.tieBreakers.join(',')} onChange={e=>settings({tieBreakers:e.target.value.split(',') as Tournament['settings']['tieBreakers']})}><option value="points,difference,goals">Puntos → Diferencia de gol → Goles a favor</option><option value="points,headToHead,difference,goals">Puntos → Enfrentamiento directo → DG → GF</option><option value="ppg,points,difference,goals">Puntos por partido → Puntos → DG → GF</option></select></label><label className="checkbox span-2"><input type="checkbox" checked={t.settings.interzonal} onChange={e=>settings({interzonal:e.target.checked})}/>Cruzar equipos libres de distintas zonas</label><label className="checkbox"><input type="checkbox" checked={t.settings.interzonalPoints} onChange={e=>settings({interzonalPoints:e.target.checked})}/>Interzonales suman puntos</label><label className="checkbox"><input type="checkbox" checked={t.settings.interzonalStats} onChange={e=>settings({interzonalStats:e.target.checked})}/>Interzonales suman a rankings</label><label>Umbral de amarillas<input type="number" min={1} value={t.settings.yellowLimit} onChange={e=>settings({yellowLimit:+e.target.value})}/></label></div><p className="info-line">Formato disponible en esta versión: liga por zonas, con o sin interzonales. Para una liga única, elegí una zona. Los playoffs se incorporarán en la siguiente etapa.</p></section><section className="panel form-panel"><h2>Canchas y calendario</h2><div className="form-grid"><label>Primera fecha<input type="date" value={t.settings.startDate} onChange={e=>settings({startDate:e.target.value})}/></label><label>Días entre fechas<input type="number" min={1} value={t.settings.intervalDays} onChange={e=>settings({intervalDays:+e.target.value})}/></label><label>Duración de partido (min)<input type="number" min={5} value={t.settings.duration} onChange={e=>settings({duration:+e.target.value})}/></label><label>Buffer entre partidos (min)<input type="number" min={0} value={t.settings.buffer} onChange={e=>settings({buffer:+e.target.value})}/></label><label>Canchas (una por línea)<textarea rows={3} value={t.settings.pitches.join('\n')} onChange={e=>settings({pitches:e.target.value.split('\n')})}/></label><label>Turnos (HH:MM, uno por línea)<textarea rows={3} value={t.settings.slots.join('\n')} onChange={e=>settings({slots:e.target.value.split('\n')})}/></label><label>Asignación<select value={t.settings.mode} onChange={e=>settings({mode:e.target.value as Tournament['settings']['mode']})}><option value="rotation">Rotación por zonas</option><option value="balanced">Distribución equilibrada</option><option value="manual">Edición manual</option></select></label><label>Semilla de generación<input type="number" value={t.settings.seed} onChange={e=>settings({seed:+e.target.value})}/></label></div><p className="info-line">Horarios de Argentina (UTC−3). Todos los instantes se almacenan en UTC. En esta versión se usa una misma disponibilidad semanal para todas las canchas.</p></section><button className="button" onClick={()=>setStep(1)}>Continuar con equipos <ArrowRight size={17}/></button></>}
 {step===1&&<><div className="section-heading"><div><h2>Equipos y planteles</h2><p className="muted">{t.entrants.length} equipos · {t.entrants.reduce((n,e)=>n+e.players.length,0)} jugadores</p></div></div>{!t.matches.length&&<div className="panel form-panel"><label>Agregar equipos (un nombre por línea)<textarea rows={4} value={names} onChange={e=>setNames(e.target.value)} placeholder={'Los Halcones\nDeportivo Norte\nAtlético Parque'}/></label><div className="toolbar"><p className="muted">Se distribuirán alternadamente entre las zonas.</p><button className="button" onClick={addTeams}><Plus size={16}/> Inscribir equipos</button></div></div>}<div className="teams-grid">{t.entrants.map(e=><TeamEditor key={e.id} entrant={e} groups={t.settings.groups} locked={!!t.matches.length} onChange={next=>update({entrants:t.entrants.map(x=>x.id===e.id?next:x)})} onDelete={()=>update({entrants:t.entrants.filter(x=>x.id!==e.id)})}/>)}</div><div className="toolbar"><p className="info-line">Los planteles solo muestran nombre deportivo y dorsal. No se recolectan DNI ni teléfonos.</p><button className="button" onClick={()=>setStep(2)}>Continuar con fixture <ArrowRight size={16}/></button></div></>}
 {step===2&&<><div className="section-heading"><div><h2>Fixture y resultados</h2><p className="muted">Primero los cruces. Después, el mejor horario para cada equipo.</p></div><div className="inline wrap">{!t.matches.some(m=>m.status==='finished')&&<button className="button" onClick={()=>generate()}><RefreshCw size={16}/>{t.matches.length?'Regenerar cruces':'Generar fixture'}</button>}{t.matches.length>0&&<button className="button secondary" onClick={()=>generate(true)}><Clock size={16}/> Reequilibrar horarios</button>}</div></div>{t.matches.length>0&&<><p className="info-line">Bloqueá los partidos que deben conservar su horario. Reequilibrar mantiene todos los rivales, jornadas y bloqueos. Los cambios públicos se auditan al guardar.</p><label className="round-select">Filtrar fecha<select value={filterRound} onChange={e=>setFilterRound(e.target.value)}><option value="all">Todas</option>{[...new Set(t.matches.map(m=>m.round))].sort((a,b)=>a-b).map(r=><option key={r} value={r}>Fecha {r}</option>)}</select></label><div className="panel table-scroll"><table className="editor-table"><thead><tr><th>Fecha</th><th>Partido</th><th>Cancha</th><th>Turno</th><th>Bloqueo</th><th>Resultado</th></tr></thead><tbody>{t.matches.filter(m=>filterRound==='all'||m.round===+filterRound).sort((a,b)=>a.round-b.round||a.slot-b.slot).map(m=><tr key={m.id}><td>{m.round}<small>{m.kind==='interzonal'?'Interzonal':m.group!==null?zone(m.group):''}</small></td><td><b>{t.entrants.find(e=>e.id===m.home)?.name}</b><small>vs {t.entrants.find(e=>e.id===m.away)?.name}</small></td><td><select aria-label="Cancha" value={m.pitch} disabled={m.locked} onChange={e=>update({matches:t.matches.map(x=>x.id===m.id?{...x,pitch:e.target.value}:x)})}>{t.settings.pitches.map(p=><option key={p}>{p}</option>)}</select></td><td><select aria-label="Turno" value={m.slot} disabled={m.locked} onChange={e=>{const slot=+e.target.value;const d=new Date(m.startsAt);const [h,min]=t.settings.slots[slot].split(':').map(Number);d.setUTCHours(h+3,min,0,0);update({matches:t.matches.map(x=>x.id===m.id?{...x,slot,startsAt:d.toISOString()}:x)});}}>{t.settings.slots.map((s,i)=><option value={i} key={i}>{s}</option>)}</select></td><td><button className={`icon-button ${m.locked?'locked':''}`} aria-label={m.locked?'Desbloquear partido':'Bloquear partido'} onClick={()=>update({matches:t.matches.map(x=>x.id===m.id?{...x,locked:!x.locked}:x)})}><Lock size={17}/></button></td><td><button className="button small-button secondary" onClick={()=>setEditing(m.id)}>{m.status==='finished'?`${m.homeScore} – ${m.awayScore}`:'Cargar'} <ChevronRight size={13}/></button></td></tr>)}</tbody></table></div></>}{!t.matches.length&&<div className="empty panel"><CalendarDays/><h3>Los próximos cruces están por salir.</h3><p>Inscribí los equipos y generá el fixture para revisarlo acá.</p></div>}{warnings.length>0&&<div className="alert warning"><AlertTriangle size={18}/><div>{warnings.slice(0,5).map((w,i)=><p key={i}>{w}</p>)}</div></div>}<div className="toolbar"><span className="muted">{t.matches.length} partidos programados</span><button className="button" onClick={()=>setStep(3)}>Revisar equidad y publicar <ArrowRight size={16}/></button></div></>}
 {step===3&&<><div className="section-heading"><div><h2>La cancha, pareja para todos.</h2><p className="muted">Revisá la programación antes de compartir el torneo.</p></div><button className="button" disabled={busy||!t.matches.length} onClick={publish}><CheckCircle2 size={17}/> {t.status==='draft'?'Publicar torneo':'Publicar cambios'}</button></div>{validateFixture(t.matches,t.settings).length?<div className="alert error"><AlertTriangle size={18}/>{validateFixture(t.matches,t.settings).join(' ')}</div>:<div className="alert success"><CheckCircle2 size={18}/> {t.matches.length?'Sin superposiciones de equipos o canchas.':'Todavía no hay fixture generado.'}</div>}<div className="panel table-scroll"><table><thead><tr><th>Equipo</th><th>PJ</th><th>Turno 1</th><th>Turno 2</th><th>Último</th><th>Últimos seguidos</th>{t.settings.pitches.map(p=><th key={p}>{p}</th>)}</tr></thead><tbody>{equity(t).map(e=><tr key={e.team}><td><b>{e.team}</b></td><td>{e.played}</td><td>{e.first}</td><td>{e.second}</td><td>{e.last}</td><td className={e.repeatedLast?'warning-text':''}>{e.repeatedLast}</td>{e.pitches.map(p=><td key={p.name}>{p.count}</td>)}</tr>)}</tbody></table></div><p className="info-line">Primero se respeta la integridad del fixture y los bloqueos. La rotación de canchas y los turnos se optimizan con costos ponderados; el equilibrio exacto depende de las restricciones de ambos rivales.</p>{t.status!=='draft'&&<div className="panel form-panel"><h3>Enlace público</h3><Link className="text-link" target="_blank" href={`/torneos/${t.slug}`}>Abrir {t.name} <ArrowUpRight size={16}/></Link><label className="status-select">Estado<select value={t.status} onChange={e=>{if(confirm('El cambio de estado quedará registrado al guardar. ¿Continuar?'))update({status:e.target.value as Tournament['status']});}}><option value="published">Publicado</option><option value="active">En juego</option><option value="finished">Finalizado</option><option value="archived">Archivado</option><option value="draft">Volver a borrador (ocultar)</option></select></label></div>}</>}
 {step===4&&<Collaborators tournamentId={t.id} isOwner={t.access==='owner'} saved={t.version>0}/>}
 {editing&&<ResultEditor t={t} match={t.matches.find(m=>m.id===editing)!} close={()=>setEditing(null)} onSave={async(m)=>{const saved=await persist({...t,matches:t.matches.map(x=>x.id===m.id?m:x)});if(saved)setEditing(null);}}/>}
 </>;
}
function TeamEditor({entrant:e,groups,locked,onChange,onDelete}:{entrant:Entrant;groups:number;locked:boolean;onChange:(e:Entrant)=>void;onDelete:()=>void}){const[name,setName]=useState(''),[number,setNumber]=useState(1);return <article className="panel team-editor"><div className="inline"><Crest name={e.name}/><label className="grow">Nombre<input value={e.name} onChange={ev=>onChange({...e,name:ev.target.value})}/></label>{!locked&&<button className="icon-button" aria-label="Quitar equipo" onClick={()=>{if(confirm(`¿Quitar ${e.name}?`))onDelete();}}><X size={17}/></button>}</div><label>Zona<select disabled={locked} value={e.group} onChange={ev=>onChange({...e,group:+ev.target.value})}>{Array.from({length:groups},(_,g)=><option value={g} key={g}>{zone(g)}</option>)}</select></label><details><summary>Plantel · {e.players.length} jugadores</summary>{e.players.map(p=><div className="roster-row" key={p.id}><span className="number">{p.number}</span>{p.name}{!locked&&<button aria-label="Quitar jugador" className="icon-button" onClick={()=>onChange({...e,players:e.players.filter(x=>x.id!==p.id)})}><X size={13}/></button>}</div>)}<form className="roster-add" onSubmit={ev=>{ev.preventDefault();if(!name.trim())return;onChange({...e,players:[...e.players,{id:uid(),name:name.trim(),number}]});setName('');setNumber(number+1);}}><input required aria-label="Nombre deportivo" placeholder="Nombre deportivo" value={name} onChange={ev=>setName(ev.target.value)}/><input required aria-label="Dorsal" type="number" min={0} max={99} value={number} onChange={ev=>setNumber(+ev.target.value)}/><button aria-label="Agregar jugador" className="button"><Plus size={16}/></button></form></details></article>}
function ResultEditor({t,match,close,onSave}:{t:Tournament;match:Match;close:()=>void;onSave:(m:Match)=>Promise<void>}){const[m,setM]=useState(()=>structuredClone(match)),[busy,setBusy]=useState(false),[error,setError]=useState(''),[teamId,setTeamId]=useState(match.home),[playerId,setPlayerId]=useState(''),[type,setType]=useState<Event['type']>('goal'),[minute,setMinute]=useState('');const home=t.entrants.find(e=>e.id===m.home)!,away=t.entrants.find(e=>e.id===m.away)!;const team=t.entrants.find(e=>e.id===teamId)!;useEffect(()=>{document.body.style.overflow='hidden';return()=>{document.body.style.overflow='';};},[]);return <div className="modal-backdrop" onClick={close}><section role="dialog" aria-modal="true" aria-labelledby="result-title" className="modal panel" onClick={e=>e.stopPropagation()}><div className="section-heading compact"><div><span className="overline">FECHA {m.round} · {m.pitch}</span><h2 id="result-title">Cargar resultado</h2></div><button autoFocus className="icon-button" aria-label="Cerrar" onClick={close}><X/></button></div><div className="score-form"><label>{home.name}<input type="number" min={0} max={99} value={m.homeScore??''} onChange={e=>setM({...m,homeScore:e.target.value===''?null:+e.target.value})}/></label><span>–</span><label>{away.name}<input type="number" min={0} max={99} value={m.awayScore??''} onChange={e=>setM({...m,awayScore:e.target.value===''?null:+e.target.value})}/></label></div><label>Estado<select value={m.status} onChange={e=>setM({...m,status:e.target.value as Match['status']})}>{['scheduled','finished','postponed','suspended','cancelled'].map(s=><option key={s} value={s}>{statusLabel[s]}</option>)}</select></label><h3 className="event-title">Goles y tarjetas</h3><div className="event-form"><select aria-label="Equipo del evento" value={teamId} onChange={e=>{setTeamId(e.target.value);setPlayerId('');}}>{[home,away].map(e=><option value={e.id} key={e.id}>{e.name}</option>)}</select><select aria-label="Jugador" value={playerId} onChange={e=>setPlayerId(e.target.value)}><option value="">Seleccionar jugador</option>{team.players.map(p=><option value={p.id} key={p.id}>{p.number} · {p.name}</option>)}</select><select aria-label="Tipo de evento" value={type} onChange={e=>setType(e.target.value as Event['type'])}>{[['goal','Gol'],['own_goal','Gol en contra'],['yellow','Amarilla'],['red','Roja'],['second_yellow','Segunda amarilla']].map(([v,l])=><option key={v} value={v}>{l}</option>)}</select><input aria-label="Minuto" placeholder="Min." type="number" min={0} max={180} value={minute} onChange={e=>setMinute(e.target.value)}/><button className="button" disabled={!playerId} onClick={()=>{setM({...m,events:[...m.events,{id:uid(),teamId,playerId,type,minute:minute===''?null:+minute}]});setMinute('');}}><Plus size={17}/></button></div>{m.events.map(e=><div className={`event-line ${e.voided?'voided':''}`} key={e.id}><span>{e.minute??'—'}′</span><b>{t.entrants.find(t=>t.id===e.teamId)?.players.find(p=>p.id===e.playerId)?.name}</b><small>{{goal:'Gol',own_goal:'Gol en contra',yellow:'Amarilla',red:'Roja',second_yellow:'Doble amarilla'}[e.type]}</small><button className="text-link" onClick={()=>setM({...m,events:m.events.map(x=>x.id===e.id?{...x,voided:!x.voided}:x)})}>{e.voided?'Restaurar':'Anular'}</button></div>)}<label className="note-label">Observación pública<textarea value={m.note} onChange={e=>setM({...m,note:e.target.value})} rows={2}/></label><p className="info-line">Solo los resultados finalizados y publicados suman a la tabla. Los eventos pueden cargarse parcialmente, pero nunca superar el marcador.</p>{error&&<p role="alert" className="alert error">{error}</p>}<div className="modal-actions"><button className="button secondary" onClick={close}>Cancelar</button><button disabled={busy} className="button" onClick={async()=>{setBusy(true);setError('');try{if(m.status==='finished'&&(m.homeScore===null||m.awayScore===null))throw Error('Completá ambos marcadores.');await onSave(m);}catch(e){setError(e instanceof Error?e.message:'Error al guardar');}finally{setBusy(false);}}}>{busy?<Loader2 size={16} className="spin"/>:<Check size={16}/>} Guardar resultado</button></div></section></div>}
